begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
\ir fixtures/gate-1-live.sql
create temporary table salon_results(name text primary key,value jsonb);grant all on salon_results to authenticated;
create function pg_temp.op(q jsonb) returns jsonb language sql volatile security invoker as $$select public.salon_operation('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000011',q,gen_random_uuid());$$;
create function pg_temp.book(i uuid,local_time text,m uuid default 'b4000000-0000-4000-8000-000000000111',v bigint default 0) returns jsonb language sql volatile security invoker as $$select jsonb_build_object('type','APPOINTMENT_SAVE','mutation_id',gen_random_uuid(),'id',i,'expected_version',v,'definition',jsonb_build_object('client_id','b4000000-0000-4000-8000-000000000031','service_id','b4000000-0000-4000-8000-000000000101','staff_membership_id',m,'local_start',local_time,'utc_offset_minutes',null,'scheduled_duration_minutes',null,'adjustment_reason',null,'notes',null,'status','CONFIRMED'));$$;
create function pg_temp.crm(q jsonb) returns jsonb language sql volatile security invoker as $$select public.crm_operation('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000011',q,gen_random_uuid());$$;
create function pg_temp.crmread(q jsonb) returns jsonb language sql volatile security invoker as $$select public.crm_read('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000011',q);$$;
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000021',true);set local role authenticated;
insert into salon_results values('hours',pg_temp.op(jsonb_build_object('type','HOURS_SAVE','mutation_id',gen_random_uuid(),'expected_version',0,'days',(select jsonb_agg(jsonb_build_object('day',d,'closed',false,'opens',540,'closes',1080)) from generate_series(1,7) d))));
insert into salon_results values('staff',pg_temp.op(jsonb_build_object('type','STAFF_SAVE','mutation_id',gen_random_uuid(),'membership_id','b4000000-0000-4000-8000-000000000111','expected_version',0,'definition',jsonb_build_object('display_name','Synthetic professional','active',true,'bookable',true,'working_capacity',null,'notes',null,'competencies',jsonb_build_array(jsonb_build_object('code','GENERAL_COLOR','level','INDEPENDENT')),'shifts',(select jsonb_agg(jsonb_build_object('day',d,'type','SHIFT','starts',540,'ends',1080)) from generate_series(1,7) d)))));
insert into salon_results values('otherstaff',pg_temp.op(jsonb_build_object('type','STAFF_SAVE','mutation_id',gen_random_uuid(),'membership_id','b4000000-0000-4000-8000-000000000113','expected_version',0,'definition',jsonb_build_object('display_name','Synthetic second professional','active',true,'bookable',true,'working_capacity',null,'notes',null,'competencies',jsonb_build_array(jsonb_build_object('code','GENERAL_COLOR','level','ASSISTED')),'shifts',(select jsonb_agg(jsonb_build_object('day',d,'type','SHIFT','starts',540,'ends',1080)) from generate_series(1,7) d)))));
insert into salon_results values('resource',pg_temp.op('{"type":"RESOURCE_SAVE","mutation_id":"b4000000-0000-4000-8000-000000000201","id":"b4000000-0000-4000-8000-000000000102","expected_version":0,"definition":{"name":"Synthetic chair","type":"CHAIR","capacity":1,"active":true}}'));
insert into salon_results values('service_command',jsonb_build_object('type','SERVICE_SAVE','mutation_id',gen_random_uuid(),'id','b4000000-0000-4000-8000-000000000101','expected_version',0,'definition',jsonb_build_object('name','Synthetic salon color','category','COLOR','description',null,'organization_wide',false,'base_duration_minutes',60,'buffer_before_minutes',5,'buffer_after_minutes',10,'base_price',1000,'tax_rate',20,'tax_inclusive',false,'requires_colorlab',true,'requires_hair_passport',true,'requires_precheck',true,'active',true,'eligible_membership_ids',jsonb_build_array('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000113'),'capabilities',jsonb_build_array(jsonb_build_object('code','GENERAL_COLOR','level','INDEPENDENT')),'resources',jsonb_build_array(jsonb_build_object('type','CHAIR','units',1)))));
insert into salon_results values('service',pg_temp.op((select value from salon_results where name='service_command')));

select is(pg_temp.op(pg_temp.book('b4000000-0000-4000-8000-000000000301','2026-10-20T10:00'))#>>'{data,status}','CONFIRMED','authoritative appointment is created through service');
select is(pg_temp.op('{"type":"APPOINTMENT_TRANSITION","mutation_id":"b4000000-0000-4000-8000-000000000311","id":"b4000000-0000-4000-8000-000000000301","expected_version":1,"status":"ARRIVED","reason":"Synthetic arrival"}')#>>'{data,status}','ARRIVED','appointment arrival validated');
select is(pg_temp.op('{"type":"APPOINTMENT_TRANSITION","mutation_id":"b4000000-0000-4000-8000-000000000312","id":"b4000000-0000-4000-8000-000000000301","expected_version":2,"status":"IN_SERVICE","reason":"Synthetic service"}')#>>'{data,status}','IN_SERVICE','appointment service validated');
reset role;
create function pg_temp.link(sid uuid,aid uuid default 'b4000000-0000-4000-8000-000000000301',v bigint default 3) returns jsonb language sql volatile as $$select pg_temp.op(jsonb_build_object('type','LINK_LIVE_SESSION','mutation_id',gen_random_uuid(),'id',aid,'expected_version',v,'live_session_id',sid));$$;
-- Historical legacy reference intentionally disagrees; it has no authority.
update public.live_sessions set appointment_link='b4000000-0000-4000-8000-000000000999',payload=jsonb_set(payload,'{appointmentLink}','"b4000000-0000-4000-8000-000000000999"') where id='b4000000-0000-4000-8000-000000000803';
set local role authenticated;
select is(pg_temp.link(gen_random_uuid())->>'code','SALON_NOT_FOUND','random live UUID rejected');
select is(pg_temp.link('b4000000-0000-4000-8000-000000000998')->>'code','SALON_NOT_FOUND','nonexistent session rejected');
select is(pg_temp.link('b4000000-0000-4000-8000-000000000803','b4000000-0000-4000-8000-000000000997')->>'code','SALON_NOT_FOUND','nonexistent appointment rejected');
reset role;
-- Synthetic identities/branches exercise each explicit relational predicate.
insert into public.clients(id,organization_id,full_name,phone,phone_normalized,created_by,updated_by,creation_location_id) values('b4000000-0000-4000-8000-000000000032','b4000000-0000-4000-8000-000000000001','Synthetic different client','+905321111111','+905321111111','b4000000-0000-4000-8000-000000000021','b4000000-0000-4000-8000-000000000021','b4000000-0000-4000-8000-000000000011');
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000022',true);set local role authenticated;
select is(public.salon_operation('b4000000-0000-4000-8000-000000000112','b4000000-0000-4000-8000-000000000012',jsonb_build_object('type','LINK_LIVE_SESSION','mutation_id',gen_random_uuid(),'id','b4000000-0000-4000-8000-000000000301','expected_version',3,'live_session_id','b4000000-0000-4000-8000-000000000803'),gen_random_uuid())->>'code','SALON_NOT_FOUND','other organization cannot link appointment/session');
reset role;select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000021',true);
insert into public.locations(id,organization_id,name,timezone) values('b4000000-0000-4000-8000-000000000019','b4000000-0000-4000-8000-000000000001','Synthetic other branch','Europe/Istanbul');
insert into public.salon_staff select (jsonb_populate_record(null::public.salon_staff,to_jsonb(s)||jsonb_build_object('location_id','b4000000-0000-4000-8000-000000000019'))).* from public.salon_staff s where membership_id='b4000000-0000-4000-8000-000000000111' and location_id='b4000000-0000-4000-8000-000000000011';
delete from public.salon_appointment_resources where appointment_id='b4000000-0000-4000-8000-000000000301';
update public.salon_appointments set location_id='b4000000-0000-4000-8000-000000000019' where id='b4000000-0000-4000-8000-000000000301';set local role authenticated;
select is(pg_temp.link('b4000000-0000-4000-8000-000000000803')->>'code','SALON_NOT_FOUND','other location cannot link');reset role;
update public.salon_appointments set location_id='b4000000-0000-4000-8000-000000000011' where id='b4000000-0000-4000-8000-000000000301';
delete from public.salon_appointment_resources where appointment_id='b4000000-0000-4000-8000-000000000301';
update public.salon_appointments set client_id='b4000000-0000-4000-8000-000000000032' where id='b4000000-0000-4000-8000-000000000301';
set local role authenticated;
select is(pg_temp.link('b4000000-0000-4000-8000-000000000803')->>'code','SALON_NOT_FOUND','different client rejected');
reset role;
update public.salon_appointments set client_id='b4000000-0000-4000-8000-000000000031' where id='b4000000-0000-4000-8000-000000000301';
set local role authenticated;
insert into salon_results values('linked',pg_temp.link('b4000000-0000-4000-8000-000000000803'));
select ok((select value ? 'data' from salon_results where name='linked'),'same organization location original client link accepted');
select is((select value#>'{data,live_session_ids}' from salon_results where name='linked'),'["b4000000-0000-4000-8000-000000000803"]'::jsonb,'public appointment projection uses relational link only');
select is((select count(*) from public.salon_appointment_live_links where live_session_id='b4000000-0000-4000-8000-000000000803'),1::bigint,'only validated relation is authoritative');
select is((select appointment_link::text from public.live_sessions where id='b4000000-0000-4000-8000-000000000803'),'b4000000-0000-4000-8000-000000000999','legacy mismatch retained without destructive rewrite');
select is((select appointment_id::text from public.salon_appointment_live_links where live_session_id='b4000000-0000-4000-8000-000000000803'),'b4000000-0000-4000-8000-000000000301','legacy field never becomes a second relational link');
select is(pg_temp.op(pg_temp.book('b4000000-0000-4000-8000-000000000302','2026-10-21T10:00'))#>>'{data,status}','CONFIRMED','second appointment created');
select is(pg_temp.op('{"type":"APPOINTMENT_TRANSITION","mutation_id":"b4000000-0000-4000-8000-000000000313","id":"b4000000-0000-4000-8000-000000000302","expected_version":1,"status":"ARRIVED","reason":"Synthetic arrival"}')#>>'{data,status}','ARRIVED','second appointment arrived');
select is(pg_temp.op('{"type":"APPOINTMENT_TRANSITION","mutation_id":"b4000000-0000-4000-8000-000000000314","id":"b4000000-0000-4000-8000-000000000302","expected_version":2,"status":"IN_SERVICE","reason":"Synthetic service"}')#>>'{data,status}','IN_SERVICE','second appointment in service');
select is(pg_temp.link('b4000000-0000-4000-8000-000000000803','b4000000-0000-4000-8000-000000000302')->>'code','SALON_CONFLICT','contradictory second appointment link rejected');
